INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Endo', 'Endo', 'endo-2007', 'Leo belongs to a poor family. Because he did not finish his studies, his only option is to work as a contractual worker in various establishments. In one job, he met a high-spirited girl named Tanya with whom he got romantically involved. In their relationship, he wishes to feel fulfillment and sense of security with her, but he is not prepared for this additional commitment.', '2007-01-01', 2007, 'assets/endo.jpg', NULL, '{"cinemalaya","indie"}', 'Filipino', TRUE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
